(()=>{const host=document.querySelector('#koica-native-map');if(!host)return;const root=host.attachShadow({mode:'open'});root.innerHTML="<style>\n:host{--blue:#003b71;--ink:#163047;--muted:#607488;--line:#dbe3e9;--bg:#f4f7fa}*{box-sizing:border-box}.atlas-workspace{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 Arial,sans-serif}header{background:var(--blue);color:white;padding:22px 5%;display:flex;align-items:center;justify-content:space-between}header b{font-size:26px;letter-spacing:3px}header a{color:white;text-decoration:none}main{max-width:1480px;margin:auto;padding:32px 4%}h1{font-size:clamp(30px,4vw,48px);line-height:1.15;margin:12px 0}h2{font-size:23px;margin:0 0 16px}.eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:12px;color:var(--muted)}p{max-width:850px}.sub{color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:25px 0}.stat,.panel{background:white;border:1px solid var(--line);border-radius:10px}.stat{padding:18px}.stat strong{display:block;font-size:30px;color:var(--blue)}.stat span{font-size:13px;color:var(--muted)}.filters{display:grid;grid-template-columns:minmax(150px,2fr) minmax(90px,1fr) minmax(130px,1.3fr) minmax(90px,1fr) minmax(110px,1fr) auto;gap:12px;margin-bottom:20px}label{font-size:12px;color:var(--muted)}input,select,button{font:inherit;border:1px solid var(--line);border-radius:6px;padding:10px;background:white;color:var(--ink)}input,select{width:100%;margin-top:5px}button{cursor:pointer}button:hover{border-color:var(--blue);color:var(--blue)}.layout{display:grid;grid-template-columns:minmax(0,3fr) minmax(250px,1fr);gap:20px}.panel{padding:22px}.mapwrap{background:#eaf2f7;overflow:hidden;border-radius:7px;position:relative}.mapwrap svg{display:block;width:100%;height:auto;touch-action:none}.country{stroke:#fff;stroke-width:.35;vector-effect:non-scaling-stroke;cursor:pointer}.country:hover{stroke:#153d66;stroke-width:1.7}.country:focus{stroke:#102a43;stroke-width:2;outline:none}.mapbuttons{position:absolute;top:10px;left:10px;display:flex;gap:6px}.mapbuttons button{font-size:14px;padding:5px 10px}.legend{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--muted);margin:12px 0;flex-wrap:wrap}.swatch{width:20px;height:12px;display:inline-block}.rank{width:100%;text-align:left;border:0;border-radius:0;padding:10px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:10px;font-size:14px}.rank span{max-width:80%}.bar{height:4px;background:#b5d2e9;margin-top:5px}.note{font-size:13px;color:var(--muted)}.results{margin-top:20px}.resulthead{display:flex;justify-content:space-between;align-items:center;gap:10px}article{padding:18px 0;border-top:1px solid var(--line)}article h3{font-size:18px;margin:0 0 8px}article p{font-size:14px;margin:10px 0}.tags{font-size:12px;color:var(--muted)}details{font-size:14px}summary{cursor:pointer;color:var(--blue)}dl{display:grid;grid-template-columns:150px 1fr;gap:5px 12px}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}.pager{display:flex;gap:15px;align-items:center}.method{margin-top:25px}a{color:var(--blue)}footer{padding:20px 0;color:var(--muted);font-size:12px}.pill{font-size:12px;border:1px solid #bbd6e9;padding:4px 9px;border-radius:20px}.loading{padding:40px}.error{color:#a22}#hover{min-height:24px;font-size:14px}#active{font-size:14px;color:var(--blue)}@media(max-width:850px){.layout{grid-template-columns:1fr}.filters{grid-template-columns:1fr 1fr}.stats{grid-template-columns:1fr 1fr}.panel{padding:16px}main{padding:22px 5%}.resulthead{align-items:flex-start;flex-direction:column}dl{grid-template-columns:1fr}dd{margin-bottom:9px}}\n\n.mapwrap{min-height:440px}.country.selected{stroke:#e8a229;stroke-width:2.5}.mapdrawer{position:absolute;right:12px;top:12px;bottom:12px;width:min(470px,52%);background:white;border:1px solid var(--line);border-radius:9px;box-shadow:0 12px 35px #14304730;overflow-y:auto;padding:20px;z-index:3}.mapdrawer[hidden]{display:none}.mapdrawer .results{border:0;padding:0;margin-top:18px}.drawerhead{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.drawerhead h2{margin:0}.drawerclose{padding:3px 10px;font-size:22px}.drawerintro{font-size:13px;color:var(--muted)}.sectorrows{margin:12px 0;font-size:13px}.sectorrow{display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--line)}.mapdrawer article h3{font-size:16px}.mapdrawer dl{grid-template-columns:1fr}.mapdrawer dd{margin-bottom:8px}.mapdrawer .resulthead h2{font-size:18px}.mapdrawer .resulthead{flex-direction:column;align-items:flex-start}.mapdrawer .pager{font-size:13px;gap:8px}.mapdrawer .pager button{padding:7px 10px} .mapwrap:has(.mapdrawer:not([hidden])){min-height:610px}.mapdrawer .tags{line-height:1.6}\n@media(max-width:650px){.mapdrawer{left:8px;right:8px;top:190px;bottom:8px;width:auto;padding:16px}.mapwrap:has(.mapdrawer:not([hidden])){min-height:780px}.mapwrap{min-height:250px}}\n\n/* Map-first workspace */\n.atlas-workspace{overflow:hidden}header{position:absolute;inset:0 0 auto;height:64px;padding:10px 22px;z-index:10}header b{font-size:22px}header a{font-size:13px}.headeractions{display:flex;gap:8px;align-items:center}.headeractions button{padding:6px 10px;font-size:13px;background:#ffffff12;color:white;border-color:#ffffff55}main{padding:0;max-width:none}main>.eyebrow,main>h1,main>p.sub,main>.pill,main>footer{display:none}.layout{display:block}.layout>section.panel{position:absolute;inset:64px 0 0;border:0;border-radius:0;padding:0;background:#eaf2f7}.layout>section.panel>h2,.layout>section.panel>p.note{display:none}.mapwrap{position:absolute;inset:0;border-radius:0;min-height:0!important}.mapwrap svg{width:100%;height:100%;position:absolute;inset:0}.filters{position:absolute;top:78px;left:20px;right:20px;z-index:5;background:#fffffff5;border:1px solid var(--line);border-radius:9px;padding:10px 14px;box-shadow:0 4px 18px #14304710;max-width:1100px;margin:0}.filters[hidden]{display:none}.filters input,.filters select{font-size:14px;padding:7px}.filters button{padding:7px;font-size:14px}.mapbuttons{top:112px;left:20px;z-index:2}#hover{position:absolute;left:20px;top:155px;max-width:40%;background:#ffffffde;border-radius:5px;padding:6px 10px;font-size:12px;pointer-events:none}.stats{position:absolute;bottom:55px;left:20px;z-index:2;display:flex;gap:0;margin:0;border:1px solid var(--line);border-radius:8px;overflow:hidden;box-shadow:0 4px 16px #14304710}.stat{padding:8px 15px;border:0;border-radius:0;border-right:1px solid var(--line);background:#fffffff2}.stat:last-child{border-right:0}.stat strong{font-size:22px}.stat span{font-size:11px}.legend{position:absolute;bottom:8px;left:20px;right:20px;z-index:2;font-size:11px;max-width:670px;background:#ffffffe8;padding:7px 10px;border-radius:5px;margin:0}.mapdrawer{top:112px;right:20px;bottom:55px;width:min(470px,42%)}.layout>aside{display:none;position:absolute;z-index:6;top:176px;left:20px;bottom:155px;width:300px;overflow-y:auto;box-shadow:0 10px 30px #14304730}.layout>aside.visible{display:block}.method{display:none}.method.visible{display:block;position:absolute;inset:85px max(20px,calc((100vw - 850px)/2)) 25px;z-index:20;overflow-y:auto;box-shadow:0 0 0 100vmax #14304788;margin:0}.method>button{float:right}.mapwrap:has(.mapdrawer:not([hidden])){min-height:0}.country{stroke-width:.5}\n@media(max-width:650px){header{padding:8px 12px;height:60px}header b{font-size:19px}header span{display:none}header a{display:none}.headeractions{gap:5px}.headeractions button{padding:5px 7px;font-size:12px}.layout>section.panel{top:60px}.filters{top:70px;left:10px;right:10px;padding:8px;grid-template-columns:1fr 1fr;gap:6px;max-height:38vh;overflow-y:auto}.filters label{font-size:11px}.filters label:first-child{grid-column:1/-1}.filters input,.filters select{margin-top:2px;padding:5px;font-size:13px}.mapbuttons{top:260px;left:10px}#hover{top:303px;left:10px;max-width:75%;font-size:11px}.stats{left:10px;right:10px;bottom:47px}.stat{flex:1;padding:6px;min-width:0}.stat strong{font-size:19px}.stat span{font-size:9px;display:block;line-height:1.3}.legend{left:10px;right:10px;bottom:5px;font-size:9px;gap:4px;padding:5px}.swatch{width:12px;height:9px}.mapdrawer{left:10px;right:10px;top:40%;bottom:125px;width:auto;padding:14px;box-shadow:0 8px 28px #14304740}.layout>aside{top:125px;left:10px;bottom:130px;width:min(310px,calc(100vw - 20px))}.method.visible{inset:72px 10px 15px}.atlas-workspace.filters-off .mapbuttons{top:15px}.atlas-workspace.filters-off #hover{top:57px}}\n\n.mapbuttons,.atlas-workspace.filters-off .mapbuttons{top:auto;bottom:var(--controls-bottom,140px);left:20px;z-index:7}.mapbuttons button{min-height:40px;min-width:40px;background:#fff;box-shadow:0 2px 10px #14304715}#hover,.atlas-workspace.filters-off #hover{top:auto;bottom:calc(var(--controls-bottom,140px) + 50px);left:20px;max-width:300px;padding:5px 8px}#hover:empty{display:none}\n@media(max-width:650px){.mapbuttons,.atlas-workspace.filters-off .mapbuttons{left:10px}#hover,.atlas-workspace.filters-off #hover{left:10px;max-width:240px}}\n\n.embedded-atlas header{height:48px;background:#f4f7fa;color:#163047;padding:6px 12px;border-bottom:1px solid #dbe3e9}.embedded-atlas header>div:first-child{display:none}.embedded-atlas .headeractions{margin-left:auto}.embedded-atlas .headeractions button{color:#163047;background:white;border-color:#b6c9d8}.embedded-atlas header a{display:none}.embedded-atlas .layout>section.panel{top:48px}.embedded-atlas .filters{top:60px}.embedded-atlas .method.visible{top:60px}\n@media(max-width:650px){.embedded-atlas .filters{top:58px}.embedded-atlas .layout>section.panel{top:48px}}\n\n:host{display:block}.atlas-workspace{position:relative;height:max(600px,calc(100dvh - 100px));overflow:hidden}.embedded-atlas header{position:absolute}.mapwrap svg{touch-action:none}.mapdrawer{overscroll-behavior:contain}.loading-error{position:absolute;top:70px;left:20px;background:white;color:#a22;padding:12px;z-index:40}\n@media(min-width:651px) and (max-width:1000px){.filters{grid-template-columns:2fr 1fr 1.3fr}.filters label,.filters button{min-width:0}}\n@media(min-width:1001px){.filters label,.filters button{min-width:0}}\n@media(min-width:651px){.mapdrawer,.layout>aside{top:var(--drawer-top,112px)}}\n</style><div class=\"atlas-workspace embedded-atlas\"><header><div><b>RICKS</b> <span style=\"font-size:12px;margin-left:16px\">ODA ATLAS</span></div><div class=\"headeractions\"><button id=\"toggle-filters\" aria-expanded=\"true\">Filters</button><button id=\"toggle-ranks\" aria-expanded=\"false\">Countries</button><button id=\"toggle-method\" aria-expanded=\"false\">About</button><a href=\"https://ricks.kr\" target=\"_blank\" rel=\"noopener\">RICKS \u2197</a></div></header><main><div class=\"eyebrow\">Korea Overseas Finance Atlas \u00b7 Pilot</div><h1>Mapping Korea\u2019s development cooperation</h1><p class=\"sub\">Explore the July 2026 IATI disclosure by recipient country, sector and project start year. This is a snapshot of disclosed activities, including volunteers and training programmes, rather than a complete historical inventory.</p><span class=\"pill\">Country-level map \u00b7 31 July 2026 source snapshot</span><div class=\"stats\"><div class=\"stat\"><strong id=\"total\">\u2014</strong><span>Activities matching filters</span></div><div class=\"stat\"><strong id=\"countries\">\u2014</strong><span>Recipient countries / territories</span></div><div class=\"stat\"><strong id=\"allocated\">\u2014</strong><span>Country-allocated activities</span></div><div class=\"stat\"><strong id=\"unallocated\">\u2014</strong><span>Regional / unspecified activities</span></div></div><div class=\"filters\"><label>Search projects<input id=\"search\" placeholder=\"e.g. hospital, Vietnam, climate\"></label><label>Agency<select id=\"agency\"><option value=\"\">All</option><option value=\"EDCF\">EDCF</option><option value=\"KOICA\">KOICA</option></select></label><label>Broad sector<select id=\"sector\"><option value=\"\">All sectors</option></select></label><label>Start year<select id=\"year\"><option value=\"\">All start years</option></select></label><label>Reported status<select id=\"status\"><option value=\"\">All statuses</option></select></label><button id=\"reset\" style=\"align-self:end\">Reset filters</button></div><div class=\"layout\"><section class=\"panel\"><h2>Where activities are reported</h2><div class=\"mapwrap\"><div class=\"mapbuttons\"><button id=\"zin\" aria-label=\"Zoom in\">+</button><button id=\"zout\" aria-label=\"Zoom out\">\u2212</button><button id=\"zreset\">Reset map</button></div><svg id=\"map\" viewBox=\"0 0 1000 490\" aria-label=\"Interactive world map of KOICA and EDCF recipient activity counts\"><g id=\"geo\"></g></svg><section class=\"mapdrawer\" id=\"drawer\" hidden aria-label=\"Selected country details\"><div class=\"drawerhead\"><h2 id=\"drawer-title\"></h2><button class=\"drawerclose\" id=\"close-drawer\" aria-label=\"Close country details\">\u00d7</button></div><div id=\"drawer-summary\" class=\"drawerintro\"></div><div id=\"drawer-sectors\" class=\"sectorrows\"></div><p class=\"note\">Country allocation only; reported cities are not verified project sites. Financial amounts are available in each activity's details.</p></section></div><div class=\"legend\"><span class=\"swatch\" style=\"background:#dce5eb\"></span>No matching disclosed activities <span class=\"swatch\" style=\"background:#bdd9ee\"></span>1\u20134 <span class=\"swatch\" style=\"background:#78acd0\"></span>5\u201319 <span class=\"swatch\" style=\"background:#347eaf\"></span>20\u201349 <span class=\"swatch\" style=\"background:#003b71\"></span>50+</div><div id=\"hover\" aria-live=\"polite\"></div><p class=\"note\">Shading represents country allocation, not project sites. Small islands remain selectable through the country list below. Grey means no matching records in this release, not absence of Korean aid.</p></section><aside class=\"panel\"><h2>Recipient rankings</h2><label>Choose country / territory<select id=\"country\"><option value=\"\">All recipients</option><option value=\"unallocated\">Regional / unspecified</option></select></label><div id=\"ranks\"></div><p class=\"note\">Rankings follow the agency, search, sector, start-year and status filters. A selected country filters the project list only.</p></aside></div><section class=\"panel results\"><div class=\"resulthead\"><div><h2>Explore the activities</h2><div id=\"active\"></div></div><button id=\"download\">Download filtered records</button></div><div id=\"list\" class=\"loading\">Loading official source data\u2026</div><div class=\"pager\"><button id=\"prev\">Previous</button><span id=\"page\"></span><button id=\"next\">Next</button></div></section><section class=\"panel method\"><button id=\"close-method\" aria-label=\"Close about panel\">Close \u00d7</button><h2>Sources and interpretation</h2><p>This atlas combines 1,646 KOICA activities from the <a href=\"https://www.data.go.kr/data/15051106/fileData.do\" target=\"_blank\" rel=\"noopener\">31 July 2026 IATI CSV</a> and 512 EDCF activities from the <a href=\"https://www.odakorea.go.kr/opm/iati_act_KR-GOV-021.xml\" target=\"_blank\" rel=\"noopener\">official IATI XML generated 31 August 2026</a> (Q2 2026 disclosure). These are different source snapshots, not a complete historical inventory or a like-for-like annual aid series. KOICA includes projects, volunteers and training; EDCF includes loans and other disclosed activities.</p><p>Use Agency to choose All, EDCF or KOICA. Both sources use a shared record format for identifiers, country, broad sector, dates, status and financial records. All 2158 identifiers are distinct. 2119 activities are allocated to 102 countries or territories; 39 regional or unspecified activities remain searchable and downloadable without invented country locations.</p><p>Country codes are crosswalked to ISO alpha-3. Broad sectors are exploratory RICKS groups: KOICA sector labels and EDCF OECD DAC sector codes are mapped to the same groups. Original labels and codes are retained. Start and end dates prefer actual dates when reported, otherwise planned dates.</p><p>Status follows the source. EDCF IATI status 1 (Pipeline / identification) is grouped under Planning; all 512 EDCF activities report this code, including some with older dates. We do not infer completion from dates. The original reported status is retained in details and downloads.</p><p>Financial records share a format while preserving source labels, currencies, dates and periods. KOICA CSV amounts and EDCF IATI budgets, planned disbursements and transactions have different definitions. Incoming funds and loan repayments are not relabelled as commitments or expenditure. Amounts are not summed across sources. Blank means missing; a reported zero remains zero.</p><p>Shading counts disclosed activities allocated to countries, not verified project sites or aid volumes. Boundary data: <a href=\"https://github.com/datasets/geo-countries\" target=\"_blank\" rel=\"noopener\">geo-countries / Natural Earth</a>. Boundaries and names do not express a position on territorial disputes.</p></section><footer>RICKS \u00b7 Hanyang Research Institute for Contemporary Korean Studies \u00b7 Exploratory research pilot</footer></main></div>";const workspace=root.querySelector('.atlas-workspace');
'use strict';
function unpack(encoded){const bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));return Promise.resolve(new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))));}
const $=id=>root.getElementById(id);let projects=[],features=[],filtered=[],shown=[],page=0;const size=12;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function options(id,values){values.forEach(v=>{let o=document.createElement('option');o.value=v;o.textContent=v;$(id).append(o)})}
function path(rings){return rings.map(r=>{let pts=r;return pts.map((p,i)=>(i?'L':'M')+((p[0]+180)/360*1000).toFixed(2)+','+((85-p[1])/180*500).toFixed(2)).join('')+'Z'}).join('')}
function buildMap(){features.filter(f=>f.properties['ISO3166-1-Alpha-3']!=='ATA').forEach(f=>{let p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',f.geometry.type==='Polygon'?path(f.geometry.coordinates):f.geometry.coordinates.map(path).join(''));p.dataset.iso=f.properties['ISO3166-1-Alpha-3'];p.dataset.name=f.properties.name;p.classList.add('country');p.setAttribute('tabindex','0');p.setAttribute('role','button');p.addEventListener('click',()=>select(p.dataset.iso));p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(p.dataset.iso)}});p.addEventListener('mouseenter',()=>{$('hover').textContent=p.getAttribute('aria-label')});p.addEventListener('mouseleave',()=>{$('hover').textContent='' });$('geo').append(p)})}
function select(iso){if(![...$('country').options].some(o=>o.value===iso)){let f=features.find(f=>f.properties['ISO3166-1-Alpha-3']===iso);let o=document.createElement('option');o.value=iso;o.textContent=f?.properties.name||iso;$('country').append(o)}$('country').value=iso;page=0;renderList();root.querySelector('.layout>aside').classList.remove('visible');$('toggle-ranks').setAttribute('aria-expanded','false')}
function update(){page=0;let q=$('search').value.toLowerCase();filtered=projects.filter(p=>(!$('agency').value||p.agency===$('agency').value)&&(!q||[p.title,p.titleKo,p.description,p.country,p.countryKo,p.sector,p.city,p.id].join(' ').toLowerCase().includes(q))&&(!$('sector').value||p.group===$('sector').value)&&(!$('year').value||String(p.year)===$('year').value)&&(!$('status').value||p.status===$('status').value));let counts={};filtered.forEach(p=>{if(p.iso)counts[p.iso]=(counts[p.iso]||0)+1});$('total').textContent=filtered.length.toLocaleString();$('countries').textContent=Object.keys(counts).length;$('allocated').textContent=filtered.filter(p=>p.iso).length.toLocaleString();$('unallocated').textContent=filtered.filter(p=>!p.iso).length;root.querySelectorAll('.country').forEach(p=>{let n=counts[p.dataset.iso]||0;p.setAttribute('fill',n>=50?'#003b71':n>=20?'#347eaf':n>=5?'#78acd0':n?'#bdd9ee':'#dce5eb');p.setAttribute('aria-label',p.dataset.name+': '+n+' matching disclosed activities')});let names=Object.fromEntries(projects.filter(p=>p.iso).map(p=>[p.iso,p.country]));$('ranks').innerHTML=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([iso,n])=>`<button class="rank" data-iso="${iso}"><span>${escape(names[iso])}<div class="bar" style="width:${n/Math.max(...Object.values(counts))*160}px"></div></span><b>${n}</b></button>`).join('');$('ranks').querySelectorAll('button').forEach(b=>b.onclick=()=>select(b.dataset.iso));renderList()}
function renderList(){let c=$('country').value;shown=filtered.filter(p=>!c||(c==='unallocated'?!p.iso:p.iso===c));$('drawer').hidden=!c;root.querySelectorAll('.country').forEach(p=>p.classList.toggle('selected',p.dataset.iso===c));if(c){$('drawer-title').textContent=$('country').selectedOptions[0].textContent;$('drawer-summary').textContent=shown.length.toLocaleString()+' disclosed activities matching current filters';let groups={};shown.forEach(p=>groups[p.group]=(groups[p.group]||0)+1);$('drawer-sectors').innerHTML=Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([g,n])=>`<div class="sectorrow"><span>${escape(g)}</span><b>${n}</b></div>`).join('')}let pages=Math.max(1,Math.ceil(shown.length/size));page=Math.max(0,Math.min(page,pages-1));$('active').textContent=`${$('country').selectedOptions[0].textContent} · ${shown.length.toLocaleString()} matching activities`;
let labels={'예산금액(원화)':'Budget amount','집행예정액(원화)':'Planned expenditure','총사업비(원화)':'Total project cost (source label)','약정액(원화)':'Commitment','지출액(원화)':'Expenditure'};
$('list').className='';$('list').innerHTML=shown.slice(page*size,(page+1)*size).map(p=>`<article><h3>${escape(p.title)}</h3><div class="tags">${escape(p.agency)} · ${escape(p.country)} · ${escape(p.group)} · ${escape(p.status)} · Start: ${escape(p.start||'Not reported')}</div><details><summary>Project details and source amounts</summary><p>${escape(p.description||'No English description reported.')}</p><dl><dt>Identifier</dt><dd>${escape(p.id)}</dd><dt>Agency</dt><dd>${escape(p.agency)}</dd><dt>Source snapshot</dt><dd>${escape(p.sourceSnapshot)}</dd><dt>Reported source status</dt><dd>${escape(p.sourceStatus)}</dd><dt>Korean title</dt><dd>${escape(p.titleKo||'Not reported')}</dd><dt>Original sector</dt><dd>${escape(p.sector||'Not reported')}${p.sectorCodes.length?' (DAC '+escape(p.sectorCodes.join(', '))+')':''}</dd><dt>Reported city</dt><dd>${escape(p.city||'Not reported')} (unverified location)</dd><dt>Reported scope</dt><dd>${escape(p.scope)}</dd><dt>End date</dt><dd>${escape(p.end||'Not reported')}</dd>${Object.entries(p.dates).map(([k,v])=>`<dt>${escape(({plannedStart:'Planned start',actualStart:'Actual start',plannedEnd:'Planned end',actualEnd:'Actual end',start:'Reported start',end:'Reported end'})[k])}</dt><dd>${escape(v||'Not reported')}</dd>`).join('')}${p.financialRecords.map(f=>`<dt>${escape(f.label)}</dt><dd>${f.value===''?'Not reported':escape(f.value)+' '+escape(f.currency)}${f.periodStart||f.periodEnd?' · Period: '+escape(f.periodStart||'?')+' to '+escape(f.periodEnd||'?'):''}${f.date?' · Transaction date: '+escape(f.date):''}${f.valueDate?' · Value date: '+escape(f.valueDate):''}</dd>`).join('')}</dl></details></article>`).join('')||'<p>No matching records. Try clearing filters.</p>';$('page').textContent=`Page ${page+1} of ${pages}`;$('prev').disabled=page===0;$('next').disabled=page>=pages-1}
$('drawer').append(root.querySelector('.results'));$('close-drawer').onclick=()=>{$('country').value='';page=0;renderList()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('drawer').hidden)$('close-drawer').click()});$('drawer').addEventListener('pointerdown',e=>e.stopPropagation());$('drawer').addEventListener('click',e=>e.stopPropagation());
['search','agency','sector','year','status'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',update));$('country').onchange=()=>{page=0;renderList()};$('reset').onclick=()=>{['search','agency','sector','year','status','country'].forEach(id=>$(id).value='');update()};$('prev').onclick=()=>{page--;renderList()};$('next').onclick=()=>{page++;renderList()};$('download').onclick=()=>{let blob=new Blob([JSON.stringify({sources:[{agency:'KOICA',snapshot:'2026-07-31'},{agency:'EDCF',snapshot:'2026-08-31',coverage:'Q2 2026'}],agencyFilter:$('agency').value||'All',note:'Snapshot; country allocations are not project coordinates. Financial fields are unreconciled source values.',records:shown},null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='korea-oda-filtered-activities.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
let zoom=1,x=0,y=0,drag=null,moved=false;function transform(){$('geo').setAttribute('transform',`translate(${x} ${y}) scale(${zoom})`)}function scale(z){let n=Math.max(1,Math.min(6,z));x=500-(500-x)*n/zoom;y=245-(245-y)*n/zoom;zoom=n;transform()}$('zin').onclick=()=>scale(zoom*1.5);$('zout').onclick=()=>scale(zoom/1.5);$('zreset').onclick=()=>{zoom=1;x=y=0;transform()};$('map').addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,tx:x,ty:y};moved=false});window.addEventListener('pointermove',e=>{if(!drag)return;let factor=mapView.width/$('map').getBoundingClientRect().width;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>5)moved=true;x=drag.tx+dx*factor;y=drag.ty+dy*factor;transform()});window.addEventListener('pointerup',()=>{drag=null});$('map').addEventListener('click',e=>{if(moved){e.stopPropagation();moved=false}},true);
Promise.all([unpack('').then(r=>{if(!r.ok)throw Error('Project data could not load');return r.json()}),unpack('').then(r=>{if(!r.ok)throw Error('Map boundaries could not load');return r.json()})]).then(([p,w])=>{projects=p;features=w.features;options('sector',[...new Set(p.map(x=>x.group))].sort());options('year',[...new Set(p.map(x=>x.year).filter(Boolean))].sort((a,b)=>b-a));options('status',[...new Set(p.map(x=>x.status))].sort());let countries=[...new Map(p.filter(x=>x.iso).map(x=>[x.iso,x.country])).entries()].sort((a,b)=>a[1].localeCompare(b[1]));countries.forEach(([iso,name])=>{let o=document.createElement('option');o.value=iso;o.textContent=name;$('country').append(o)});buildMap();update()}).catch(e=>{$('list').className='error';$('list').textContent=e.message+' — please reload.'});

const filterBox=root.querySelector('.filters'),rankBox=root.querySelector('.layout>aside'),methodBox=root.querySelector('.method');
$('toggle-filters').onclick=()=>{filterBox.hidden=!filterBox.hidden;$('toggle-filters').setAttribute('aria-expanded',String(!filterBox.hidden));workspace.classList.toggle('filters-off',filterBox.hidden);fitMapViewport()};
$('toggle-ranks').onclick=()=>{let open=rankBox.classList.toggle('visible');$('toggle-ranks').setAttribute('aria-expanded',String(open))};
function closeMethod(){methodBox.classList.remove('visible');$('toggle-method').setAttribute('aria-expanded','false')}
$('toggle-method').onclick=()=>{let open=methodBox.classList.toggle('visible');$('toggle-method').setAttribute('aria-expanded',String(open))};$('close-method').onclick=closeMethod;
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMethod();rankBox.classList.remove('visible');$('toggle-ranks').setAttribute('aria-expanded','false')}});
$('country').addEventListener('change',()=>{rankBox.classList.remove('visible');$('toggle-ranks').setAttribute('aria-expanded','false')});

// Match the SVG viewport to the available screen without stretching geography.
// A tall viewport shows a closer view; dragging reaches the other continents.
let mapView={width:1000,height:490};
function fitMapViewport(){const rect=$('map').getBoundingClientRect();if(!rect.width||!rect.height)return;const ratio=rect.width/rect.height;mapView=ratio<1000/490?{width:490*ratio,height:490}:{width:1000,height:1000/ratio};$('map').setAttribute('viewBox',`${500-mapView.width/2} ${245-mapView.height/2} ${mapView.width} ${mapView.height}`);const filtersRect=filterBox.getBoundingClientRect();workspace.style.setProperty('--drawer-top',Math.max(64,filterBox.hidden?64:filtersRect.bottom-workspace.getBoundingClientRect().top+12)+'px');const stats=root.querySelector('.stats').getBoundingClientRect();const mapRect=root.querySelector('.mapwrap').getBoundingClientRect();workspace.style.setProperty('--controls-bottom',Math.max(90,mapRect.bottom-stats.top+12)+'px')}
new ResizeObserver(fitMapViewport).observe(root.querySelector('.mapwrap'));new ResizeObserver(fitMapViewport).observe(root.querySelector('.stats'));new ResizeObserver(fitMapViewport).observe(filterBox);fitMapViewport();

})();
